import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount } from '../src/invoices.js';
import { renderInvoiceText } from '../src/render.js';

test('createInvoice with valid single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
  assert.equal(result.value.lines[2].name, 'Printed flyer A4 (each)');
});

test('createInvoice with invalid customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice with invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '15-01-2026',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice with invalid date (non-existent)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice with non-string date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: 20260115,
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice with empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice with non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: null,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice with non-integer qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5.5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice with zero qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice with negative qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice with unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input lines array', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const originalLine = { ...lines[0] };

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines,
  });

  assert.deepEqual(lines[0], originalLine);
});

test('createInvoice returns a new lines array', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines,
  });

  assert.notEqual(result.value.lines, lines);
});

test('createInvoice with various VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice with large quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'STICKER', qty: 10000 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 10000);
});

test('createInvoice stops at first validation error in lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'UNKNOWN-SKU', qty: 10 },
      { sku: 'DEV-HOUR', qty: -1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal with single item', () => {
  const line = { qty: 1, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineTotal(line), 9500);
});

test('lineTotal with large quantity', () => {
  const line = { qty: 10000, unitPrice: 50, vatRate: 21 };
  assert.equal(lineTotal(line), 500000);
});

test('lineTotal with expensive item', () => {
  const line = { qty: 2, unitPrice: 245000, vatRate: 21 };
  assert.equal(lineTotal(line), 490000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 20, unitPrice: 9500, vatRate: 21 },
      { sku: 'COPY-HOUR', name: 'Copywriting (hour)', qty: 5, unitPrice: 6000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 190000 + 30000);
  assert.equal(totals.total, 305000);
});

test('invoiceTotals with empty invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals from createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 9500 * 10 + 120000);
  assert.equal(totals.total, 215000);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
      { qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 3700 + 60000);
  assert.equal(totals.total, 111200);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const originalInvoice = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), originalInvoice);
});

test('lineTotal does not mutate line', () => {
  const line = { qty: 5, unitPrice: 9500, vatRate: 21 };
  const originalLine = { ...line };

  lineTotal(line);
  assert.deepEqual(line, originalLine);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
  assert.equal(result.value.lines[1].name, 'Copywriting (hour)');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].unitPrice, 6000);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].unitPrice, 9500);
});

test('addLine with multiple existing lines increases qty in correct position', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'COPY-HOUR', name: 'Copywriting (hour)', qty: 2, unitPrice: 6000, vatRate: 21 },
    ],
  };

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[1].qty, 15);
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[2].qty, 2);
});

test('addLine with invalid qty', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 }],
  };

