});

test('lineVat with high discount reduces VAT accordingly', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 50 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const netAmount = total - discount;
  const expectedVat = Math.round((netAmount * 21) / 100);
  assert.equal(lineVat(line), expectedVat);
});

