test('renderInvoiceText shows VAT when present', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const rendered = renderInvoiceText(result.value);

  assert.equal(rendered.ok, true);
  const text = rendered.value;
  assert.match(text, /VAT:/);
  assert.match(text, /\+€/);
});

test('renderInvoiceText shows VAT on own line above total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const rendered = renderInvoiceText(result.value);

  assert.equal(rendered.ok, true);
  const lines = rendered.value.split('\n');
  const totalLineIndex = lines.findIndex((line) => line.startsWith('Total:'));
  const vatLineIndex = lines.findIndex((line) => line.startsWith('VAT:'));

  assert.ok(vatLineIndex >= 0);
  assert.ok(totalLineIndex > vatLineIndex);
});

test('renderInvoiceText does not show VAT when 0% rate', () => {
