test('invoiceTotals with discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const lineTotal_ = 10 * 9500;
  const discount = Math.round((lineTotal_ * 10) / 100);
  const netAmount = lineTotal_ - discount;
  const vat = Math.round((netAmount * 21) / 100);
  assert.equal(totals.subtotal, lineTotal_);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, lineTotal_ - discount + vat);
});

test('invoiceTotals with multiple discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const line1Total = 5 * 8500;
  const line1Discount = Math.round((line1Total * 10) / 100);
  const line1Net = line1Total - line1Discount;
  const line1Vat = Math.round((line1Net * 21) / 100);
  const line2Total = 10 * 9500;
  const line2Discount = Math.round((line2Total * 5) / 100);
  const line2Net = line2Total - line2Discount;
  const line2Vat = Math.round((line2Net * 21) / 100);
  const expectedSubtotal = line1Total + line2Total;
  const expectedDiscount = line1Discount + line2Discount;
  const expectedVat = line1Vat + line2Vat;
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

