test('invoiceTotals with tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const lineTotal_ = 10 * 9500;
  const discount = Math.round((lineTotal_ * 5) / 100);
  const netAmount = lineTotal_ - discount;
  const vat = Math.round((netAmount * 21) / 100);
  assert.equal(totals.subtotal, lineTotal_);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, lineTotal_ - discount + vat);
});

